import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { useAuth } from '../services/AuthContext';
import api from '../services/api';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [activeRentals, setActiveRentals] = useState([]);
  const [rentalHistory, setRentalHistory] = useState([]);

  useEffect(() => {
    fetchActiveRentals();
    fetchRentalHistory();
  }, []);

  const fetchActiveRentals = async () => {
    try {
      const response = await api.get('/rentals/active');
      setActiveRentals(Array.isArray(response.data) ? response.data : [response.data].filter(Boolean));
    } catch (error) {
      console.log('No active rentals');
    }
  };

  const fetchRentalHistory = async () => {
    try {
      const response = await api.get('/rentals/history');
      setRentalHistory(response.data);
    } catch (error) {
      console.error('Failed to fetch rental history');
    }
  };

  const needsDeposit = !user?.depositMade;

  return (
    <div>
      <Navbar />
      <div className="container">
        <div className="card">
          <h2 style={{ marginBottom: '20px', color: '#1f2937' }}>
            Dashboard
          </h2>

          {needsDeposit && (
            <div className="alert alert-warning">
              <h3 style={{ marginBottom: '8px', fontSize: '1.125rem' }}>Initial Deposit Required</h3>
              <p style={{ marginBottom: '12px' }}>
                Add ₹300 to your wallet and receive ₹100 cashback bonus.
              </p>
              <button 
                className="btn btn-primary"
                onClick={() => navigate('/wallet')}
              >
                Add Deposit
              </button>
            </div>
          )}

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', alignItems: 'start' }}>
            <div className="card" style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', height: '100%' }}>
              <h3 style={{ marginBottom: '16px', fontSize: '1.25rem' }}>Umbrella Rental System</h3>
              <div style={{ display: 'grid', gap: '16px' }}>
                <div>
                  <h4 style={{ marginBottom: '8px', fontSize: '1rem' }}>Pricing</h4>
                  <p style={{ fontSize: '0.95rem', opacity: 0.95 }}>₹7 per hour | ₹70 per day (24 hours)</p>
                </div>
                <div>
                  <h4 style={{ marginBottom: '8px', fontSize: '1rem' }}>How It Works</h4>
                  <ul style={{ fontSize: '0.95rem', opacity: 0.95, paddingLeft: '20px', lineHeight: '1.8' }}>
                    <li>Make an initial deposit of ₹300 and get ₹100 cashback</li>
                    <li>Browse available umbrellas across campus locations</li>
                    <li>Select and rent umbrellas instantly</li>
                    <li>Track your active rentals in real-time</li>
                    <li>Return umbrellas at any campus location</li>
                  </ul>
                </div>
              </div>
            </div>

            <div className="card" style={{ background: 'linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%)', border: '1px solid #0ea5e9' }}>
              <h3 style={{ color: '#0c4a6e', marginBottom: '12px', fontSize: '1.125rem' }}>Wallet Balance</h3>
              <div style={{ fontSize: '2.5rem', fontWeight: 'bold', color: '#0c4a6e', marginBottom: '16px' }}>
                ₹{user?.walletBalance || 0}
              </div>
              <button 
                className="btn btn-primary"
                onClick={() => navigate('/wallet')}
              >
                Add Money
              </button>
            </div>

            <div className="card" style={{ background: 'linear-gradient(135deg, #f0fdf4 0%, #dcfce7 100%)', border: '1px solid #10b981' }}>
              <h3 style={{ color: '#065f46', marginBottom: '12px', fontSize: '1.125rem' }}>Rent Umbrella</h3>
              <p style={{ color: '#065f46', marginBottom: '16px' }}>
                Browse available umbrellas across campus locations.
              </p>
              <button 
                className="btn btn-success"
                onClick={() => navigate('/umbrellas')}
                disabled={needsDeposit}
              >
                Browse Umbrellas
              </button>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '20px', marginTop: '20px' }}>
            {activeRentals.length > 0 && (
              <div className="card" style={{ background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)', border: '1px solid #f59e0b' }}>
                <h3 style={{ color: '#92400e', marginBottom: '12px', fontSize: '1.125rem' }}>Active Rentals ({activeRentals.length})</h3>
                <div style={{ maxHeight: '200px', overflowY: 'auto', marginBottom: '16px' }}>
                  {activeRentals.map((rental, index) => (
                    <div key={rental._id} style={{ 
                      padding: '12px', 
                      background: 'rgba(255, 255, 255, 0.5)',
                      borderRadius: '8px',
                      marginBottom: index < activeRentals.length - 1 ? '8px' : '0'
                    }}>
                      <p style={{ color: '#92400e', fontSize: '0.9rem', fontWeight: '600' }}>
                        {rental.umbrella?.umbrellaId}
                      </p>
                      <p style={{ color: '#78350f', fontSize: '0.875rem' }}>
                        Started: {new Date(rental.startTime).toLocaleString()}
                      </p>
                    </div>
                  ))}
                </div>
                <button 
                  className="btn btn-primary"
                  onClick={() => navigate('/tracking')}
                >
                  Track Location
                </button>
              </div>
            )}

            <div className="card">
              <h3 style={{ marginBottom: '16px', color: '#1f2937', fontSize: '1.125rem' }}>Rental History</h3>
              {rentalHistory.length === 0 ? (
                <p style={{ color: '#6b7280', textAlign: 'center', padding: '20px' }}>
                  No rental history available.
                </p>
              ) : (
                <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
                  {rentalHistory.slice(0, 5).map((rental) => (
                    <div key={rental._id} style={{ 
                      padding: '12px', 
                      border: '1px solid #e5e7eb', 
                      borderRadius: '8px', 
                      marginBottom: '8px',
                      display: 'flex',
                      justifyContent: 'space-between',
                      alignItems: 'center'
                    }}>
                      <div>
                        <strong>{rental.umbrella?.umbrellaId}</strong>
                        <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>
                          {new Date(rental.startTime).toLocaleDateString()}
                        </div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div style={{ fontWeight: 'bold' }}>₹{rental.totalAmount}</div>
                        <div style={{ fontSize: '0.875rem', color: '#6b7280' }}>
                          {rental.duration}h
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
